import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const f=JSON.parse('{"title":"三里屯太古里","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/sanlitun.md","filePath":"landmarks/sanlitun.md","lastUpdated":1787033866000}'),n={name:"landmarks/sanlitun.md"};function d(s,t,o,i,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="三里屯太古里" tabindex="-1">三里屯太古里 <a class="header-anchor" href="#三里屯太古里" aria-label="Permalink to &quot;三里屯太古里&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1531058020387-3be344556be6?w=1200" alt="三里屯太古里"></p><blockquote><p>&quot;潮流与夜色在此交汇。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>三里屯太古里位于北京市朝阳区三里屯地区，由南区、北区两大开放式街区构成，是北京最具潮流感的商业街区。这里汇集了国际高端品牌、设计师买手店、潮流旗舰店、众多酒吧与餐厅，以及标志性的时尚街区建筑群。白天是逛街购物的潮流地标，夜晚则是京城著名的夜生活中心，处处霓虹闪烁、人潮涌动。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放（商户10:00-22:00）</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">2-3小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">四季皆宜，夜晚最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁10号线团结湖站或农业展览馆站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市朝阳区三里屯路19号</td></tr></tbody></table><h2 id="街区特色" tabindex="-1">街区特色 <a class="header-anchor" href="#街区特色" aria-label="Permalink to &quot;街区特色&quot;">​</a></h2><h3 id="南区潮流街区" tabindex="-1">南区潮流街区 <a class="header-anchor" href="#南区潮流街区" aria-label="Permalink to &quot;南区潮流街区&quot;">​</a></h3><p>南区以潮流品牌、快时尚和开放式街区著称，橙色建筑群充满设计感，是拍照打卡的热门地点。</p><h3 id="北区高端消费" tabindex="-1">北区高端消费 <a class="header-anchor" href="#北区高端消费" aria-label="Permalink to &quot;北区高端消费&quot;">​</a></h3><p>北区聚集国际一线品牌旗舰店与高端餐饮，氛围更为精致，是时尚买手的必逛之地。</p><h3 id="三里屯酒吧街" tabindex="-1">三里屯酒吧街 <a class="header-anchor" href="#三里屯酒吧街" aria-label="Permalink to &quot;三里屯酒吧街&quot;">​</a></h3><p>三里屯周边拥有京城最著名的酒吧街，从精酿啤酒到鸡尾酒一应俱全，是体验北京夜生活的经典去处。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>三里屯太古里南区 → 潮流买手店 → 北区高端品牌 → 三里屯酒吧街 → 深夜夜宵</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁10号线团结湖站或农业展览馆站步行约10分钟</li><li><strong>错峰</strong>：白天逛街人少清净，夜晚酒吧街最热闹</li><li><strong>拍照</strong>：南区的橙色街区和开放空间是网红打卡地</li><li><strong>餐饮</strong>：北区高端、南区多元，周边还有大量胡同美食</li><li><strong>搭配</strong>：与亮马河、蓝色港湾等商圈串联游玩</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">10号线团结湖站或农业展览馆站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">三里屯周边多路公交</td></tr><tr><td style="text-align:left;"><strong>打车</strong></td><td style="text-align:left;">定位&quot;三里屯太古里&quot;即可</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">亮马河国际风情水岸</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">滨水夜景</td></tr><tr><td style="text-align:left;">蓝色港湾</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">欧式风情商圈</td></tr><tr><td style="text-align:left;">工人体育场</td><td style="text-align:center;">步行10分钟</td><td style="text-align:left;">文体地标</td></tr><tr><td style="text-align:left;">朝阳公园</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">城市公园</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>三里屯是中国时尚消费文化的发源地之一，从最早的酒吧一条街到如今的开放式潮流街区，它见证并引领了北京乃至中国的消费升级与流行文化变迁。</p><hr><p><strong>📍 地址</strong>：北京市朝阳区三里屯路19号 <strong>🚇 地铁</strong>：10号线团结湖站 / 农业展览馆站</p><p><strong>💡 Tips</strong>：想看夜色和潮流就去南区和酒吧街，想买高端品牌去北区，白天拍照更出片。</p>',29)])])}const c=e(n,[["render",d]]);export{f as __pageData,c as default};
